"""Export only the producer artifacts generated by this setup into data-only Parquet."""
from pathlib import Path
import pickle,json
import pandas as pd
from parquet_adapter import ParquetIntradayProcessedData,ROOT
work=Path('/root/autodl-tmp/qlib-work')
stocks=sorted(p.name.removesuffix('.pkl.target') for p in (ROOT/'orders/train').glob('*.pkl.target'))
checks=[]
for kind in ['feature','backtest']:
    out=ROOT/'parquet'/kind
    out.mkdir(parents=True,exist_ok=True)
    for stock in stocks:
        source=(ROOT/'pickle'/kind/f'{stock}.pkl').resolve()
        assert source.is_relative_to((ROOT/'pickle').resolve())
        # These artifacts were produced locally by the upstream preprocessing job in this workspace.
        with source.open('rb') as f: produced=pickle.load(f)
        frame=produced.handler.fetch(level=None)
        target=out/f'{stock}.parquet'
        frame.to_parquet(target)
        restored=pd.read_parquet(target)
        pd.testing.assert_frame_equal(frame,restored)
        day=pd.Timestamp(frame.index.get_level_values('datetime')[len(frame)//2]).normalize()
        cols=list(frame.columns)
        processed=ParquetIntradayProcessedData(ROOT/'pickle',stock,day,cols,[],backtest=(kind=='backtest'))
        expected=produced.handler.fetch(pd.IndexSlice[stock,day:day.replace(hour=23,minute=59,second=59)],level=None).reset_index()
        expected=expected.drop(columns='instrument').set_index('datetime')
        pd.testing.assert_frame_equal(processed.today,expected)
        checks.append({'kind':kind,'stock':stock,'rows':len(frame),'columns':len(frame.columns)})
    print(kind,'converted',len(stocks),'stocks; full-frame and daily-slice equality passed',flush=True)
(work/'results/parquet_manifest.json').write_text(json.dumps(checks,indent=2))
(work/'results/parquet.done').touch()
